				replaced.Text = arg
				tokensCopy = append(tokensCopy, replaced)
			}
		} else {
			replaced := token
			replaced.Text = repl.ReplaceKnown(token.Text, "")
			tokensCopy = append(tokensCopy, replaced)
		}
